import data from './certificates.data.json';

/**
 * Certificates, newest first. Generated by scripts/certificates.py from the PDFs in
 * content-source/certificates/originals/: title, issuer and date are read off each certificate.
 * Only the rendered images are published, never the PDFs.
 */
export interface Certificate {
  id: string;
  title: string;
  issuer: string;
  platform: string;
  /** YYYY-MM */
  date: string;
  kind: 'course' | 'project' | 'specialization';
  topic: Topic;
  card: string;
  full: string;
  width: number;
  height: number;
}

export type Topic = 'AI' | 'Data' | 'Python' | 'Java' | 'R' | 'C++' | 'Software' | 'Vision';

/** The topic sticker on each card, from the title (first match wins). */
const TOPICS: [Topic, RegExp][] = [
  ['Software', /data structures|algorithm/i],
  ['Vision', /image|video/i],
  ['AI', /artificial intelligence|machine learning|neural|natural language|reinforcement|retrieval augmented|recommendation|agents|langchain|\bAI\b/i],
  ['Python', /python/i],
  ['R', /\bR\b/],
  ['Java', /java|jdbc/i],
  ['C++', /C\+\+/],
  ['Data', /data|statistic|probability|sql|database/i],
  ['Software', /./],
];

const cards = import.meta.glob<string>('../assets/certificates/*.card.webp', { eager: true, query: '?url', import: 'default' });
const fulls = import.meta.glob<string>('../assets/certificates/*.webp', { eager: true, query: '?url', import: 'default' });
const asset = (map: Record<string, string>, file: string) => {
  const url = map[`../assets/certificates/${file}`];
  if (!url) throw new Error(`Missing certificate image ${file}; run scripts/certificates.py export`);
  return url;
};

export const certificates: Certificate[] = data.map((d) => ({
  id: d.id,
  title: d.title,
  issuer: d.issuer,
  platform: d.platform,
  date: d.date,
  kind: d.kind as Certificate['kind'],
  topic: TOPICS.find(([, re]) => re.test(d.title))![0],
  card: asset(cards, `${d.id}.card.webp`),
  full: asset(fulls, `${d.id}.webp`),
  width: d.width,
  height: d.height,
}));

const MONTH = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
/** "2024-08" → "Aug 2024" */
export const monthYear = (date: string) => `${MONTH[Number(date.slice(5, 7)) - 1]} ${date.slice(0, 4)}`;
